TASK AND SPECIFICATIONS
{
  "schema_version": 1,
  "id": "SELF007",
  "kind": "self_built",
  "title": "Duty standby alternation with healthy pump fallback",
  "difficulty": "medium",
  "provenance": {
    "source_type": "independent_synthesis",
    "source_file": "scripts/build_self_dataset.py",
    "source_index": 7,
    "adaptation": "Independently specified for this project; no public task was copied. The coding assistant chose the state variables, priority order and fixed scan traces, then reviewed the traces against a separate Python transition implementation.",
    "rationale": "Two sump pumps share wear by alternating the preferred pump only after a demand episode that actually delivered pumping.",
    "review": "Assistant consistency review of initialization, simultaneous commands, retained state and recovery boundaries; independent Python oracle checked against manual expected traces. Not an industrial safety certification or external expert review."
  },
  "requirements": "LeadA initializes TRUE. During Demand choose preferred healthy pump, falling back to the other if the preferred pump is faulted. Both faulty means neither runs. Fault changes cause immediate fallback within the episode. Never run both. When Demand falls FALSE, toggle LeadA exactly once if any pump ran during that just-ended continuous demand episode. An all-faulted episode with no running scan does not toggle the lead. Without Demand both pumps are FALSE. LeadA is the retained preference for the current or next episode, not a report of which fallback pump is presently running.",
  "scenario": "Two sump pumps share wear by alternating the preferred pump only after a demand episode that actually delivered pumping.",
  "interface": [
    {
      "direction": "INPUT",
      "name": "Demand",
      "type": "BOOL",
      "description": "Sump pumping demand"
    },
    {
      "direction": "INPUT",
      "name": "FaultA",
      "type": "BOOL",
      "description": "Pump A unavailable"
    },
    {
      "direction": "INPUT",
      "name": "FaultB",
      "type": "BOOL",
      "description": "Pump B unavailable"
    },
    {
      "direction": "OUTPUT",
      "name": "PumpA",
      "type": "BOOL",
      "description": "Pump A run command"
    },
    {
      "direction": "OUTPUT",
      "name": "PumpB",
      "type": "BOOL",
      "description": "Pump B run command"
    },
    {
      "direction": "OUTPUT",
      "name": "LeadA",
      "type": "BOOL",
      "description": "TRUE selects A as preferred pump"
    }
  ],
  "initial_conditions": {
    "LeadA": true,
    "previous_demand": false,
    "episode_served": false
  },
  "scan_semantics": "At scan k, sample every input once, read retained pre-state q[k], execute one transition, and observe outputs O[k] at the end of that same scan. Updated state becomes q[k+1]. Reset the instance before each test. Step 0 executes normally; initial conditions describe pre-state, not an extra delayed scan. All timing in this task is explicitly counted in invocations, not wall time.",
  "safety_priority": [
    "Faulted pumps never run",
    "No demand forces both off",
    "Prefer selected lead, then healthy fallback"
  ],
  "assumptions": [],
  "atomic_propositions": {
    "Demand": "Sump pumping demand Boolean names are propositions; numeric names appear only inside defined predicates.",
    "FaultA": "Pump A unavailable Boolean names are propositions; numeric names appear only inside defined predicates.",
    "FaultB": "Pump B unavailable Boolean names are propositions; numeric names appear only inside defined predicates.",
    "PumpA": "Pump A run command Boolean names are propositions; numeric names appear only inside defined predicates.",
    "PumpB": "Pump B run command Boolean names are propositions; numeric names appear only inside defined predicates.",
    "LeadA": "TRUE selects A as preferred pump Boolean names are propositions; numeric names appear only inside defined predicates.",
    "first": "True only on the first invocation after resetting the FB instance.",
    "qLeadA": "Pre-scan lead preference, initially TRUE.",
    "completedServed": "Pre-scan Demand was TRUE, current Demand is FALSE and a pump ran in that episode."
  },
  "ltl": [
    {
      "id": "P1",
      "formula": "G(!(PumpA & PumpB))",
      "explanation": "At most one pump runs."
    },
    {
      "id": "P2",
      "formula": "G((!Demand | FaultA) -> !PumpA)",
      "explanation": "A cannot run without demand or with its fault."
    },
    {
      "id": "P3",
      "formula": "G((!Demand | FaultB) -> !PumpB)",
      "explanation": "B cannot run without demand or with its fault."
    },
    {
      "id": "P4",
      "formula": "G((Demand & LeadA & !FaultA) -> PumpA)",
      "explanation": "A is selected when it is the healthy lead."
    },
    {
      "id": "P5",
      "formula": "G((Demand & !LeadA & !FaultB) -> PumpB)",
      "explanation": "B is selected when it is the healthy lead."
    },
    {
      "id": "P6",
      "formula": "G(completedServed -> (LeadA <-> !qLeadA))",
      "explanation": "Toggle once on a served demand's falling edge."
    },
    {
      "id": "P7",
      "formula": "G(!completedServed -> (LeadA <-> qLeadA))",
      "explanation": "Unserved episodes and held demand preserve preference."
    }
  ],
  "tests": [
    {
      "id": "alternate",
      "purpose": "Served episodes alternate preference",
      "steps": [
        {
          "inputs": {
            "Demand": false,
            "FaultA": false,
            "FaultB": false
          },
          "expected": {
            "PumpA": false,
            "PumpB": false,
            "LeadA": true
          }
        },
        {
          "inputs": {
            "Demand": true,
            "FaultA": false,
            "FaultB": false
          },
          "expected": {
            "PumpA": true,
            "PumpB": false,
            "LeadA": true
          }
        },
        {
          "inputs": {
            "Demand": true,
            "FaultA": false,
            "FaultB": false
          },
          "expected": {
            "PumpA": true,
            "PumpB": false,
            "LeadA": true
          }
        },
        {
          "inputs": {
            "Demand": false,
            "FaultA": false,
            "FaultB": false
          },
          "expected": {
            "PumpA": false,
            "PumpB": false,
            "LeadA": false
          }
        },
        {
          "inputs": {
            "Demand": false,
            "FaultA": false,
            "FaultB": false
          },
          "expected": {
            "LeadA": false
          }
        },
        {
          "inputs": {
            "Demand": true,
            "FaultA": false,
            "FaultB": false
          },
          "expected": {
            "PumpA": false,
            "PumpB": true,
            "LeadA": false
          }
        },
        {
          "inputs": {
            "Demand": false,
            "FaultA": false,
            "FaultB": false
          },
          "expected": {
            "LeadA": true
          }
        }
      ]
    },
    {
      "id": "fallback",
      "purpose": "Fault fallback, unserved episode and recovery",
      "steps": [
        {
          "inputs": {
            "Demand": true,
            "FaultA": true,
            "FaultB": true
          },
          "expected": {
            "PumpA": false,
            "PumpB": false,
            "LeadA": true
          }
        },
        {
          "inputs": {
            "Demand": false,
            "FaultA": true,
            "FaultB": true
          },
          "expected": {
            "LeadA": true
          }
        },
        {
          "inputs": {
            "Demand": true,
            "FaultA": true,
            "FaultB": false
          },
          "expected": {
            "PumpA": false,
            "PumpB": true,
            "LeadA": true
          }
        },
        {
          "inputs": {
            "Demand": true,
            "FaultA": false,
            "FaultB": false
          },
          "expected": {
            "PumpA": true,
            "PumpB": false,
            "LeadA": true
          }
        },
        {
          "inputs": {
            "Demand": false,
            "FaultA": true,
            "FaultB": true
          },
          "expected": {
            "LeadA": false
          }
        }
      ]
    }
  ]
}
